<?php
require_once 'includes/components.php'; require_once 'config.php'; require_once 'content_repository.php'; ensureContentSchema($conn);
$reviews=contentRows($conn,"SELECT name,rating,type,message,created_at FROM feedback WHERE status='approved' ORDER BY created_at DESC LIMIT 12");
