?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Đánh giá khách hàng | NALI Dental</title><?php renderSeo('Đánh giá khách hàng | NALI Dental','Các phản hồi được khách gửi và đã được duyệt công khai tại NALI Dental.'); ?><link rel="stylesheet" href="common.css"><link rel="stylesheet" href="theme.css"><link rel="stylesheet" href="content-pages.css"></head><body><?php renderHeader(); ?><section class="content-hero"><h1>Phản hồi khách hàng</h1><p>Chỉ phản hồi được quản trị viên duyệt mới xuất hiện tại đây. Không dùng lời đánh giá mẫu để quảng bá.</p></section><main class="content-wrap"><div class="content-grid"><?php foreach($reviews as $r):?><article class="content-card"><div class="review-stars"><?=str_repeat('★',max(0,min(5,(int)$r['rating'])))?></div><p>“<?=htmlspecialchars($r['message'])?>”</p><div class="review-icon">💬</div><p class="meta"><?=htmlspecialchars($r['name'])?><?= $r['type'] ? ' · '.htmlspecialchars($r['type']) : '' ?></p></article><?php endforeach;?></div><?php if(!$reviews):?><div class="content-empty">Chưa có phản hồi nào được duyệt công khai.</div><?php endif;?><section style="margin-top:40px"><h2>Đánh giá Google</h2><?php if($validEmbed):?><iframe title="Đánh giá Google của NALI Dental" src="<?=htmlspecialchars($embed,ENT_QUOTES,'UTF-8')?>" width="100%" height="420" style="border:0;border-radius:16px" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe><?php else:?><div class="content-empty">Phòng khám chưa liên kết hồ sơ Google Business đã xác minh. Quản trị viên có thể thêm URL nhúng trong trang Quản trị nội dung.</div><?php endif;?></section><div class="content-actions"><a class="content-button" href="contact.php#feedbackForm">Gửi phản hồi</a></div></main><?php renderFooter(); ?></body></html>
